// Replays proto/testdata/escrow_vectors.json (generated by
// proto/go/escrow/vectors_test.go) against proto/ts/src/escrow. The record
// inputs are a non-repeating byte stream, so an offset that drifts on either
// side decodes a different value here. If this fails, the TS port has drifted from
// Go — fix the divergence rather than regenerating the fixture.

import { describe, it, expect } from 'vitest'
import * as fs from 'node:fs'
import * as path from 'node:path'
import { fileURLToPath } from 'node:url'
import { hex } from '@scure/base'

import {
    classify,
    computeFeeBreakdown,
    decodeNodeRecord,
    decodeOperatorRecord,
    decodeTicketRecord,
    boundedRingGapIters,
    freeQuotaBoxKey,
    gapOpUpsForIters,
    netFee,
    nodeBoxKey,
    nodeBoxPrefixForOperator,
    NODE_RECORD_SIZE,
    openBoxReferences,
    OPERATOR_RECORD_SIZE,
    operatorBoxKey,
    ringGapIters,
    settleInnerCount,
    TICKET_RECORD_SIZE,
    ticketBoxKey,
    windowedRingRevenue,
    type RecordMetrics,
} from '../src/escrow/index.js'
import * as escrow from '../src/escrow/index.js'

type Json = Record<string, any> // eslint-disable-line @typescript-eslint/no-explicit-any

const here = path.dirname(fileURLToPath(import.meta.url))
const v = JSON.parse(
    fs.readFileSync(path.resolve(here, '..', '..', 'testdata', 'escrow_vectors.json'), 'utf8'),
) as Json

// Renders a decoded value the way the Go generator does: uint64 and the
// narrowed ints as decimal strings, byte arrays as hex.
function str(x: unknown): unknown {
    if (typeof x === 'bigint' || typeof x === 'number') return String(x)
    if (x instanceof Uint8Array) return hex.encode(x)
    if (Array.isArray(x)) return x.map(str)
    return x
}

function metricsVector(m: RecordMetrics): Json {
    return {
        last_activity_at: str(m.lastActivityAt),
        tickets_opened: str(m.ticketsOpened),
        tickets_settled: str(m.ticketsSettled),
        tickets_lapsed_settled: str(m.ticketsLapsedSettled),
        tickets_refunded_inactive: str(m.ticketsRefundedInactive),
        total_refunded_inactive_usdc: str(m.totalRefundedInactiveUsdc),
        tickets_protested: str(m.ticketsProtested),
        total_protested_usdc: str(m.totalProtestedUsdc),
        tickets_frozen_dispute: str(m.ticketsFrozenDispute),
        total_frozen_dispute_usdc: str(m.totalFrozenDisputeUsdc),
        latency_total_ms: str(m.latencyTotalMs),
        latency_ewma_ms: str(m.latencyEwmaMs),
        total_revenue_gross: str(m.totalRevenueGross),
        buckets_last_day: str(m.bucketsLastDay),
        revenue_buckets: str(m.revenueBuckets),
        total_input_tokens: str(m.totalInputTokens),
        output_units: str(m.outputUnits),
        tokens_per_sec_ewma: str(m.tokensPerSecEwma),
    }
}

describe('escrow_vectors.json', () => {
    it('is the schema this test expects', () => {
        expect(v.version).toBe(1)
    })

    // A renamed key in the fixture would otherwise turn a section's loop into
    // zero tests and pass.
    it('has cases in every section', () => {
        expect(Object.keys(v.constants ?? {}).length).toBeGreaterThan(0)
        for (const section of [
            v.box_keys.ticket,
            v.box_keys.operator,
            v.box_keys.node,
            v.box_keys.free_quota,
            v.box_keys.open_box_references,
            v.records.tickets,
            v.records.operators,
            v.records.nodes,
            v.revenue_windows,
            v.classify,
            v.fees.net_fee,
            v.fees.fee_breakdown,
            v.fees.settle_inner_count,
            v.fees.ring_gap,
            v.fees.gap_op_ups_for_iters,
        ]) {
            expect(Array.isArray(section) && section.length > 0).toBe(true)
        }
    })

    describe('constants', () => {
        // Every TS export named in the fixture must exist and match Go's value.
        for (const [name, want] of Object.entries(v.constants as Record<string, string>)) {
            it(name, () => {
                const got = (escrow as Record<string, unknown>)[name]
                expect(typeof got === 'number' || typeof got === 'bigint').toBe(true)
                expect(String(got)).toBe(want)
            })
        }
    })

    describe('box keys', () => {
        for (const c of v.box_keys.ticket) {
            it(`ticket ${c.ticket_id_hex}`, () => {
                expect(hex.encode(ticketBoxKey(hex.decode(c.ticket_id_hex)))).toBe(c.key_hex)
            })
        }
        for (const c of v.box_keys.operator) {
            it(`operator ${c.operator_id}`, () => {
                expect(hex.encode(operatorBoxKey(BigInt(c.operator_id)))).toBe(c.key_hex)
            })
        }
        for (const c of v.box_keys.node) {
            it(`node ${c.operator_id}/${c.node_id}`, () => {
                expect(hex.encode(nodeBoxKey(BigInt(c.operator_id), BigInt(c.node_id)))).toBe(c.key_hex)
                expect(hex.encode(nodeBoxPrefixForOperator(BigInt(c.operator_id)))).toBe(c.operator_prefix_hex)
            })
        }
        for (const c of v.box_keys.free_quota) {
            it(`free quota ${c.payer}`, () => {
                expect(hex.encode(freeQuotaBoxKey(c.payer))).toBe(c.key_hex)
            })
        }
        for (const c of v.box_keys.open_box_references) {
            it(`open() references: ${c.name}`, () => {
                const refs = openBoxReferences(
                    BigInt(c.operator_id),
                    BigInt(c.node_id),
                    hex.decode(c.ticket_id_hex),
                    c.payer,
                    BigInt(c.max_price),
                )
                expect(refs.map((r) => hex.encode(r))).toEqual(c.keys_hex)
            })
        }
    })

    describe('record decoders', () => {
        it('agree with Go on the record sizes', () => {
            expect(TICKET_RECORD_SIZE).toBe(v.records.ticket_record_size)
            expect(OPERATOR_RECORD_SIZE).toBe(v.records.operator_record_size)
            expect(NODE_RECORD_SIZE).toBe(v.records.node_record_size)
        })

        for (const c of v.records.tickets) {
            it(`ticket: ${c.name}`, () => {
                const data = hex.decode(c.data_hex)
                if (c.error) {
                    expect(() => decodeTicketRecord(data)).toThrow(new Error(c.error_message))
                    return
                }
                const r = decodeTicketRecord(data)
                expect({
                    payer_addr: r.payerAddr,
                    operator_id: str(r.operatorId),
                    node_id: str(r.nodeId),
                    operator_owner_addr: r.operatorOwnerAddr,
                    node_signing_addr: r.nodeSigningAddr,
                    max_price: str(r.maxPrice),
                    opened_at: str(r.openedAt),
                    expires_at: str(r.expiresAt),
                    settlement_grace_seconds: str(r.settlementGraceSeconds),
                    status: str(r.status),
                    pending_amount: str(r.pendingAmount),
                    pending_by: str(r.pendingBy),
                    pending_digest_hex: str(r.pendingDigest),
                    pending_ttft_ms: str(r.pendingTtftMs),
                    pending_decode_ms: str(r.pendingDecodeMs),
                    pending_input_count: str(r.pendingInputCount),
                    pending_output_count: str(r.pendingOutputCount),
                    pending_output_usage_type: str(r.pendingOutputUsageType),
                    pending_aux_output_usage_type: str(r.pendingAuxOutputUsageType),
                    pending_aux_output_count: str(r.pendingAuxOutputCount),
                    fee_bps: str(r.feeBps),
                    discount_bps: str(r.discountBps),
                    reserved_slots_hex: str(r.reservedSlots),
                }).toEqual(c.ticket)
            })
        }

        for (const c of v.records.operators) {
            it(`operator: ${c.name}`, () => {
                const data = hex.decode(c.data_hex)
                if (c.error) {
                    expect(() => decodeOperatorRecord(BigInt(c.operator_id), data)).toThrow(
                        new Error(c.error_message),
                    )
                    return
                }
                const r = decodeOperatorRecord(BigInt(c.operator_id), data)
                expect({
                    id: str(r.id),
                    owner_addr: r.ownerAddr,
                    status: str(r.status),
                    nfd_app_id: str(r.nfdAppId),
                    next_node_id: str(r.nextNodeId),
                    live_node_count: str(r.liveNodeCount),
                    metrics: metricsVector(r),
                    usdc_escrowed: str(r.usdcEscrowed),
                    reserved_slots_hex: str(r.reservedSlots),
                    latency_samples: str(r.latencySamples),
                }).toEqual(c.operator)
            })
        }

        for (const c of v.records.nodes) {
            it(`node: ${c.name}`, () => {
                const data = hex.decode(c.data_hex)
                const [op, node] = [BigInt(c.operator_id), BigInt(c.node_id)]
                if (c.error) {
                    expect(() => decodeNodeRecord(op, node, data)).toThrow(new Error(c.error_message))
                    return
                }
                const r = decodeNodeRecord(op, node, data)
                expect({
                    operator_id: str(r.operatorId),
                    node_id: str(r.nodeId),
                    status: str(r.status),
                    signing_addr: r.signingAddr,
                    base_url: r.baseUrl,
                    metrics: metricsVector(r),
                    usdc_escrowed: str(r.usdcEscrowed),
                    staging: str(r.staging),
                    reserved_slots_hex: str(r.reservedSlots),
                    latency_samples: str(r.latencySamples),
                }).toEqual(c.node)
            })
        }
    })

    describe('revenue windows', () => {
        for (const c of v.revenue_windows) {
            it(c.name, () => {
                const got = windowedRingRevenue(
                    BigInt(c.buckets_last_day),
                    c.revenue_buckets.map((b: string) => BigInt(b)),
                    BigInt(c.current_day),
                    BigInt(c.window_days),
                )
                expect(String(got)).toBe(c.want)
            })
        }
    })

    describe('classify', () => {
        for (const c of v.classify) {
            it(c.name, () => {
                const got = classify(
                    {
                        status: Number(c.status),
                        pendingBy: Number(c.pending_by),
                        expiresAt: BigInt(c.expires_at),
                        settlementGraceSeconds: BigInt(c.settlement_grace_seconds),
                    },
                    new Date(Number(c.now_unix_ms)),
                )
                expect(got).toBe(c.verdict)
            })
        }
    })

    describe('fees', () => {
        for (const c of v.fees.net_fee) {
            it(`netFee(${c.amount_charged}, ${c.fee_bps}, ${c.discount_bps})`, () => {
                expect(String(netFee(BigInt(c.amount_charged), BigInt(c.fee_bps), BigInt(c.discount_bps)))).toBe(c.want)
                // TicketRecord decodes the bps as numbers; that path must agree too.
                expect(String(netFee(BigInt(c.amount_charged), Number(c.fee_bps), Number(c.discount_bps)))).toBe(c.want)
            })
        }
        for (const c of v.fees.fee_breakdown) {
            it(`computeFeeBreakdown(${c.amount_charged}, ${c.max_price}, ${c.fee_bps})`, () => {
                const b = computeFeeBreakdown(
                    BigInt(c.amount_charged),
                    BigInt(c.max_price),
                    BigInt(c.fee_bps),
                    BigInt(c.discount_bps),
                )
                expect([b.amountCharged, b.netFee, b.refund, b.totalDebit].map(String)).toEqual([
                    c.amount_charged,
                    c.net_fee,
                    c.refund,
                    c.total_debit,
                ])
            })
        }
        for (const c of v.fees.settle_inner_count) {
            it(`settleInnerCount(${c.amount_charged}, ${c.max_price})`, () => {
                expect(String(settleInnerCount(BigInt(c.amount_charged), BigInt(c.max_price)))).toBe(c.want)
            })
        }
        for (const c of v.fees.ring_gap) {
            it(`ring gap ${c.last_day} → ${c.current_day}`, () => {
                const [last, cur] = [BigInt(c.last_day), BigInt(c.current_day)]
                expect(String(ringGapIters(last, cur))).toBe(c.ring_gap_iters)
                expect(String(boundedRingGapIters(last, cur))).toBe(c.bounded_ring_gap_iters)
            })
        }
        for (const c of v.fees.gap_op_ups_for_iters) {
            it(`gapOpUpsForIters(${c.iters})`, () => {
                expect(String(gapOpUpsForIters(BigInt(c.iters)))).toBe(c.want)
            })
        }
    })
})

// Guards Go gets from its types and so the fixture cannot express: Go's ids are
// uint64 and its ring is a [30]uint64, while TS takes a bigint and an array.
describe('escrow input guards (TS only)', () => {
    // DataView.setBigUint64 wraps silently, so without the guard -1n names
    // operator 2^64-1's box and 2^64+5 names node 5's.
    it('refuses ids outside uint64', () => {
        expect(() => operatorBoxKey(-1n)).toThrow(new RangeError('uint64 out of range: -1'))
        expect(() => nodeBoxKey(1n, 1n << 64n)).toThrow(/uint64 out of range/)
        expect(() => nodeBoxPrefixForOperator(1n << 64n)).toThrow(/uint64 out of range/)
        expect(hex.encode(operatorBoxKey(0xffff_ffff_ffff_ffffn))).toMatch(/ffffffffffffffff$/)
    })

    // A wrong-length id names a box the contract never creates, so a read of
    // it would report "absent" instead of failing.
    it('refuses a ticket id that is not 16 bytes', () => {
        expect(() => ticketBoxKey(new Uint8Array(15))).toThrow(/must be 16 bytes \(got 15\)/)
        expect(() => ticketBoxKey(new Uint8Array(17))).toThrow(/must be 16 bytes \(got 17\)/)
    })

    // Go decodes this box and keeps the raw bytes; TS refuses it rather than
    // return a U+FFFD-substituted URL that differs from the stored one.
    it('refuses a node base URL that is not valid UTF-8', () => {
        const base = (v.records.nodes as Json[]).find((c) => !c.error)!
        const data = hex.decode(base.data_hex)
        const url = new Uint8Array([...new TextEncoder().encode('https://'), 0xff, 0xfe])
        data[33] = url.length
        data.fill(0, 34, 34 + 248)
        data.set(url, 34)
        expect(() => decodeNodeRecord(BigInt(base.operator_id), BigInt(base.node_id), data)).toThrow(
            /baseUrl is not valid UTF-8/,
        )
        // The same bytes with the invalid tail cut off by the length byte decode.
        data[33] = url.length - 2
        expect(decodeNodeRecord(BigInt(base.operator_id), BigInt(base.node_id), data).baseUrl).toBe('https://')
    })

    // A short ring would otherwise read its missing slots as zero revenue.
    it('refuses a revenue ring that is not 30 buckets', () => {
        expect(() => windowedRingRevenue(1n, Array<bigint>(29).fill(1n), 1n, 1n)).toThrow(
            /has 29 buckets, want 30/,
        )
        expect(() => windowedRingRevenue(1n, Array<bigint>(31).fill(1n), 1n, 1n)).toThrow(
            /has 31 buckets, want 30/,
        )
    })
})
